//扫描状态正常直接查询，不正常跳框提示
scanAfterAction = function (id) {
    if ($("#数据检查").val() !== "") {
        alert($("#数据检查").val());
        return;
    }
    var dmPara = reParaList(); // 获取界面上的参数
    showModelData(dmPara); // 触发查询
};
editWebs=function(){
	var max=$("#需领数量").val()*1
	var val=$("#消耗数量").val()*1
	if(val==max){
             //两者相等直接返回
		showModelData(null);
	}else{
           //重新计算需领数量
          $("#需领数量").val(max-val);
      //    $("#库位").val("");
          $("#消耗数量").val("");
          $("#序列号").val("");
          $("#选择库存").val("");
           //需要手动刷新详情界面
           var con = plus.webview.getWebviewById('contentlist');
	   mui.fire(con,'contentlist_local',{});
	}
}

